window.OmniUI=(()=>{'use strict';let returnFocus=null;const root=()=>document.querySelector('[role=dialog]:not([hidden])')||document;const items=()=>Array.from(root().querySelectorAll('button,input,select,a,textarea,[tabindex="0"]')).filter(e=>!e.disabled&&e.getClientRects().length&&!e.closest('[hidden]')&&!e.classList.contains('skip'));function focus(e){if(e){e.focus();e.scrollIntoView({block:'nearest',inline:'nearest'})}}function modal(id){returnFocus=document.activeElement;document.getElementById(id).hidden=false;document.getElementById('content').setAttribute('inert','');focus(items()[0])}function close(){const d=root();if(d!==document)d.hidden=true;document.getElementById('content').removeAttribute('inert');focus(returnFocus?.isConnected?returnFocus:items()[0])}function move(a){const all=items(),current=document.activeElement;if(!all.length)return false;if(!all.includes(current)){focus(all[0]);return true}const r=current.getBoundingClientRect(),cx=r.x+r.width/2,cy=r.y+r.height/2;const horizontal=['left','right'].includes(a),sign=['left','up'].includes(a)?-1:1;const candidates=all.filter(e=>e!==current).map(e=>{const x=e.getBoundingClientRect();const dx=x.x+x.width/2-cx,dy=x.y+x.height/2-cy;return{e,along:(horizontal?dx:dy)*sign,off:Math.abs(horizontal?dy:dx)}}).filter(x=>x.along>4).sort((a,b)=>(a.along+a.off*3)-(b.along+b.off*3));if(candidates[0])focus(candidates[0].e);return true}function controller(a){if(window.handlePageController?.(a))return true;if(['left','right'].includes(a)&&document.activeElement?.tagName==='SELECT'){const e=document.activeElement;if(!items().includes(e))return false;let i=e.selectedIndex+(a==='right'?1:-1);while(i>=0&&i<e.options.length&&e.options[i].disabled)i+=a==='right'?1:-1;if(i>=0&&i<e.options.length){e.selectedIndex=i;e.dispatchEvent(new Event('change',{bubbles:true}))}return true}if(['left','right','up','down'].includes(a))return move(a);if(a==='cross'){const e=document.activeElement;if(items().includes(e)){if(e.tagName!=='SELECT')e.click();return true}focus(items()[0]);return true}if(a==='circle'&&root()!==document){close();return true}return false}function notify(message){document.getElementById('status').textContent=message}let sequence=0;async function request(method,params,mock){if(typeof window.omnibloomHost?.request!=='function'){if(!window.omnibloomHost&&window.OMNI_PREVIEW&&mock)return mock();throw Error('HOST_UNAVAILABLE')}const reply=await window.omnibloomHost.request({version:1,id:'ui-'+Date.now()+'-'+(++sequence),method,params});if(reply?.ok!==true)throw Error(reply?.code||'REQUEST_FAILED');return reply.result}
document.addEventListener('keydown',e=>{if(e.key==='Tab'&&root()!==document){const all=items(),i=all.indexOf(document.activeElement);e.preventDefault();focus(all[(i+(e.shiftKey?-1:1)+all.length)%all.length]);return}const a={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right',Escape:'circle'}[e.key];if(a&&(!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||a==='circle')&&controller(a))e.preventDefault()});document.querySelectorAll('[data-close]').forEach(b=>b.onclick=close);window.omniPadController=controller;window.omniMediaController=controller;return{items,focus,modal,close,move,notify,request};})();

OmniUI.setGlyphs=function(value){const kind=value==='xbox'?'xbox':'playstation';document.querySelectorAll('.hint').forEach(e=>e.textContent=kind==='xbox'?'D-pad Move · A Select · B Back':'D-pad Move · × Select · ○ Back');return kind};
(()=>{let value='playstation';try{value=typeof window.omnibloomHost?.getGlyphs==='function'?window.omnibloomHost.getGlyphs():localStorage.getItem('ob.glyphs')||'playstation'}catch(_){}OmniUI.setGlyphs(value)})();
